"""Build the "inside" firmware (inside.elf) with LLVM; no model is loaded.

  QWENPUTER_RV_MAP=inside python chipformer/rv/env/inside/build.py     (from experimental/riscv)

The chat harness (harness.c) is compiled to a wasm32 module (harness.wasm) and linked into the
DROM; firmware.c runs it with wasm3 v0.5.0 (fetched and checked by sha256 into the cache, like
env/doom fetches Doom), all as RV32IM guest code for the circuit. qlibc.c, start.S and the
include directory are env/doom's. prefix.h (the template's system turn the module writes into
Qwen) is regenerated from a local Qwen3.5 chat_template.jinja when one is found ($QWEN_SNAPSHOT
or the HF cache); otherwise the checked-in prefix.h is used.
"""

import hashlib
import json
import os
import shutil
import subprocess
import sys
import tarfile
import tempfile
import urllib.request
from pathlib import Path

os.environ.setdefault("QWENPUTER_RV_MAP", "inside")
HERE = Path(__file__).resolve().parent
DOOM = HERE.parent / "doom"
sys.path[:0] = [str(HERE), str(HERE.parents[3])]

import template

from chipformer.rv import spec as S

WASM3_URL = "https://github.com/wasm3/wasm3/archive/refs/tags/v0.5.0.tar.gz"
WASM3_SHA256 = "b778dd72ee2251f4fe9e2666ee3fe1c26f06f517c3ffce572416db067546536c"
CACHE = Path.home() / ".cache/qwenputer"
STACK = 64 * 1024
WASM3_SOURCES = ["m3_bind", "m3_code", "m3_compile", "m3_core", "m3_emit", "m3_env", "m3_exec",
                 "m3_function", "m3_module", "m3_parse"]
WASM3_CONFIG = ["-Dd_m3HasFloat=0", "-Dd_m3VerboseErrorMessages=0", "-Dd_m3LogOutput=0",
                "-Dd_m3MaxFunctionStackHeight=500", "-Dd_m3CodePageAlignSize=4096",
                "-Dd_m3MaxLinearMemoryPages=1", "-Dd_m3Use32BitSlots=1"]


def toolchain() -> tuple[str, list[str], list[str]]:
    """clang, the ELF linker command and the wasm linker command (rust-lld's flavors)."""
    import importlib.util
    spec = importlib.util.spec_from_file_location("doom_build", DOOM / "build.py")
    doom = importlib.util.module_from_spec(spec)
    sys.path.insert(0, str(DOOM))  # env/doom/build.py imports its wad.py
    spec.loader.exec_module(doom)
    clang, elf = doom.toolchain()
    if elf[1:] == ["-flavor", "gnu"]:
        wasm = [elf[0], "-flavor", "wasm"]
    else:
        wasm = [os.environ.get("WASM_LD") or shutil.which("wasm-ld") or "wasm-ld"]
    return clang, elf, wasm


def wasm3() -> Path:
    """wasm3's source directory, fetched once into the cache (an untrusted download: it is
    unpacked into its own new directory, and nothing in it is run)."""
    tree = CACHE / "wasm3-0.5.0"
    if not (tree / "source" / "wasm3.h").is_file():
        CACHE.mkdir(parents=True, exist_ok=True)
        tmp = Path(tempfile.mkdtemp(prefix="wasm3-", dir=CACHE))
        archive = tmp / "wasm3.tar.gz"
        with urllib.request.urlopen(WASM3_URL) as r:
            archive.write_bytes(r.read())
        digest = hashlib.sha256(archive.read_bytes()).hexdigest()
        if digest != WASM3_SHA256:
            raise SystemExit(f"wasm3 download: sha256 {digest}, expected {WASM3_SHA256}")
        with tarfile.open(archive) as t:
            t.extractall(tmp / "x", filter="data")
        (tmp / "x" / "wasm3-0.5.0").rename(tree)
        shutil.rmtree(tmp)
    return tree / "source"


def prefix() -> Path:
    """prefix.h: the template's system turn (regenerated when a Qwen3.5 template is found)."""
    out = HERE / "prefix.h"
    snap = template.snapshot()
    if snap and (snap / "chat_template.jinja").is_file():
        from chipformer.rv.neural_harness import SYSTEM, TOOL
        arrays, table = template.token_arrays(SYSTEM, TOOL, snap)
        out.write_text("/* Generated by build.py from Qwen3.5's chat_template.jinja and tokenizer:\n"
                       " * the system turn (neural_harness.SYSTEM and TOOL) and the turn pieces as\n"
                       " * Qwen's own tokens, in putchar values: 0..255 a byte's token, 256 + k a\n"
                       " * special token, 264 + j the j-th token of tokens.json. */\n"
                       + template.c_arrays(arrays))
        (HERE / "tokens.json").write_text(json.dumps(table) + "\n")
    elif not out.is_file():
        raise SystemExit("No Qwen3.5 chat_template.jinja (set QWEN_SNAPSHOT) and no prefix.h.")
    return out


def linker_script() -> str:
    ram_top = S.RAM_BASE + 4 * S.RAM_WORDS
    return f"""/* Generated by env/inside/build.py from spec.py's "inside" address map. */
ENTRY(_start)
MEMORY
{{
  RAM (rw) : ORIGIN = {S.RAM_BASE + S.DATA_BASE:#x}, LENGTH = {4 * S.RAM_WORDS - S.DATA_BASE:#x}
  DROM (r) : ORIGIN = {S.DROM_BASE:#x}, LENGTH = {4 * S.DROM_WORDS:#x}
  ROM (rx) : ORIGIN = {S.ROM_BASE:#x}, LENGTH = {4 * S.ROM_WORDS:#x}
}}
SECTIONS
{{
  .text : {{ *(.text.init) *(.text .text.*) }} > ROM
  .rodata : {{
    *(.rodata .rodata.* .srodata .srodata.*)
    *(.init_array .init_array.* .fini_array .fini_array.* .eh_frame .eh_frame_hdr)
  }} > DROM
  .data : {{ *(.data .data.* .sdata .sdata.*) }} > RAM
  .tdata : {{ __tls_base = .; *(.tdata .tdata.*) }} > RAM
  .tbss : {{ *(.tbss .tbss.*) }} > RAM
  .bss : {{
    . = . + SIZEOF(.tbss);
    *(.bss .bss.* .sbss .sbss.*) *(COMMON)
    . = ALIGN(16);
    __heap_start = .;
  }} > RAM
  __heap_end = {ram_top - STACK:#x};
  ASSERT(__heap_start <= __heap_end, "the firmware's data does not fit the RAM")
}}
"""


def module(clang: str, wasm_ld: list[str], tmp: Path) -> Path:
    """harness.c -> harness.wasm (wasm32 MVP, one 64 KB page, no libc)."""
    obj, out = tmp / "harness.wasm.o", HERE / "harness.wasm"
    subprocess.run([clang, "--target=wasm32", "-mcpu=mvp", "-nostdlib", "-ffreestanding",
                    "-O2", "-Wall", "-I", str(HERE), "-c", str(HERE / "harness.c"), "-o",
                    str(obj)], check=True)
    subprocess.run([*wasm_ld, "--no-entry", "--export=run", "--initial-memory=65536",
                    "--max-memory=65536", "-z", "stack-size=16384", "--gc-sections",
                    "--strip-all", str(obj), "-o", str(out)], check=True)
    return out


def build(out: Path = HERE / "inside.elf") -> Path:
    assert S.MAP == "inside", "build with QWENPUTER_RV_MAP=inside"
    clang, lld, wasm_ld = toolchain()
    src = wasm3()
    prefix()
    flags = ["--target=riscv32-unknown-none-elf", "-march=rv32im", "-mabi=ilp32",
             "-msmall-data-limit=0", "-mno-relax", "-O2", "-nostdlibinc",
             "-fno-stack-protector", "-fno-common", "-ffunction-sections", "-fdata-sections",
             "-w", "-I", str(HERE / "include"), "-I", str(DOOM / "include"), "-I", str(src),
             f"-DTEXT_ADDR={S.TEXT_ADDR:#x}", *WASM3_CONFIG]
    with tempfile.TemporaryDirectory(prefix="qinside-") as tmp:
        tmp = Path(tmp)
        wasm = module(clang, wasm_ld, tmp)
        (tmp / "inside.ld").write_text(linker_script())
        units = [src / f"{n}.c" for n in WASM3_SOURCES] + [
            HERE / "firmware.c", DOOM / "qlibc.c", DOOM / "start.S", HERE / "module.S"]
        objs = []
        for unit in units:
            obj = tmp / (unit.name + ".o")
            # -ffreestanding implies -fno-builtin, so wasm3's memcpy-based loads and stores would
            # be calls; only qlibc.c (which defines memcpy) needs it
            free = ["-ffreestanding"] if unit.name == "qlibc.c" else []
            subprocess.run([clang, *flags, *free, f'-DMODULE_PATH="{wasm}"', "-c", str(unit),
                            "-o", str(obj)], check=True)
            objs.append(str(obj))
        subprocess.run([*lld, "-m", "elf32lriscv", "--no-relax", "--gc-sections", "-T",
                        str(tmp / "inside.ld"), *objs, "-o", str(out)], check=True)
    return out


if __name__ == "__main__":
    print(build())
